package solution

func Solve(items []any) int {
	sum := 0
	for _, it := range items {
		switch v := it.(type) {   // branch on the dynamic type
		case int:
			sum += v               // v is an int
		case float64:
			sum += int(v)          // truncate the float toward zero
		default:
			// ignore strings, bools, nil, etc.
		}
	}
	return sum
}

