type MyError struct{ msg string }
func (e *MyError) Error() string { return e.msg }

func do() error {
	// success path: return the untyped nil for the interface
	return nil
}

func main() {
	if err := do(); err != nil {
		fmt.Println("failed:", err)
	} else {
		fmt.Println("ok")
	}
}

func Flatten(x any) []int {
	switch v := x.(type) {
	case int:
		return []int{v}              // leaf: a single int
	case []any:
		var out []int
		for _, e := range v {
			out = append(out, Flatten(e)...) // recurse into the slice
		}
		return out
	default:
		return nil                   // ignore everything else
	}
}
